import json, sys, re, datetime

def ts(e):
    t = e.get('timestamp')
    if not t: return None
    try:
        return datetime.datetime.fromisoformat(t.replace('Z','+00:00'))
    except Exception:
        return None

def short(s, n=400):
    s = re.sub(r'\s+', ' ', s or '').strip()
    return s[:n] + ('…' if len(s) > n else '')

path = sys.argv[1]
maxtxt = int(sys.argv[2]) if len(sys.argv) > 2 else 400
prev = None
start = None
for line in open(path):
    line = line.strip()
    if not line: continue
    try: e = json.loads(line)
    except Exception: continue
    t = ts(e)
    if t and start is None: start = t
    off = f"{(t-start).total_seconds():7.1f}" if (t and start) else "      ?"
    typ = e.get('type')
    msg = e.get('message') or {}
    role = msg.get('role')
    content = msg.get('content')
    if isinstance(content, str):
        content = [{'type':'text','text':content}]
    if not isinstance(content, list):
        content = []
    for c in content:
        ct = c.get('type')
        if ct == 'text':
            txt = short(c.get('text'), maxtxt)
            if txt: print(f"[{off}] {role.upper()}: {txt}")
        elif ct == 'thinking':
            pass
        elif ct == 'tool_use':
            inp = json.dumps(c.get('input'))[:260]
            print(f"[{off}]   >TOOL {c.get('name')} {inp}")
        elif ct == 'tool_result':
            body = c.get('content')
            if isinstance(body, list):
                body = ' '.join(x.get('text','') for x in body if isinstance(x, dict))
            err = c.get('is_error')
            body = short(str(body), 300 if err else 160)
            print(f"[{off}]   <RES{'!ERR' if err else ''} {body}")
    if typ not in ('user','assistant') and e.get('attachment'):
        a = e['attachment']
        print(f"[{off}]   ~ATTACH {a.get('type')} {short(str(a.get('hookName') or a.get('content')),120)}")

